catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
    var ga = new GlideAjax('EvenUtils'); // Use the correct Script Include name
    ga.addParam('sysparm_name', 'getEventDetails'); // Call method on the Script Include
    ga.addParam('sysparm_eventId', newValue); // Pass the event sys_id

    ga.getXMLAnswer(function(response) {
        try {
            var data = JSON.parse(response);


            if (data.error) {
                g_form.addErrorMessage(data.error);
            } else {
                var msg = 'Event Details:<br>' +
                          '<b>Name:</b> ' + data.event_name + '<br>' +
                          '<b>Date:</b> ' + data.event_date + '<br>' +
                          '<b>Location:</b> ' + data.location + '<br>' +
                          '<b>Planner:</b> ' + data.planner;

                g_form.addInfoMessage(msg);

                // Optional: populate other form fields if you have them
                // g_form.setValue('u_event_name', data.event_name);
            }
        } catch (e) {
            g_form.addErrorMessage('Failed to parse event details.');
        }
    });

   //Type appropriate comment here, and begin script below

}
